/* ===== Đi dạo: nạp mô hình người có xương (public/people/p<k>.glb) và một nhân vật đang diễn =====
   - stRigLoad(k): import() động GLTFLoader + SkeletonUtils (chunk riêng, trang thường không tải), nạp p<k>.glb một lần, nhớ đệm theo k.
     Lỗi bất kỳ (mạng, file hỏng, thiếu đoạn) → console.warn một lần cho mô hình đó, trả null, không thử lại trong phiên; promise không bao giờ bị từ chối.
   - stRigSource: chuẩn hóa cảnh đã nạp: lớp 1 (không vào phản chiếu nước), không đổ / nhận bóng, tắt frustumCulled (hộp bao theo tư thế gốc sai khi diễn),
     vật liệu metalness 0, roughness 0.85; mảnh alpha (alphaMode MASK) giữ alphaTest, không trộn trong suốt. Tốc độ tự nhiên từng đoạn đọc từ extras.speed.
   - StRig: một bản sao (SkeletonUtils.clone, dùng chung geometry / texture / vật liệu với nguồn) + AnimationMixer riêng.
     pose(): trọng số đích từ stClipMix (anim.ts), làm mượt về đích với hằng thời gian anim.fade; walk / jog / sprint đồng pha bằng một pha chung 0–1
     (đặt action.time = pha × thời lượng đoạn, timeScale 0 để mixer không tự tua); photo LoopOnce + clampWhenFinished, phát lại từ đầu mỗi lần chuyển sang dáng chụp ảnh.
     dt kẹp [0, stroll.dtMax] (tab ẩn rồi quay lại không làm nhảy pha). Không cấp phát mỗi khung (D-018).
   - Mô hình: mét, chân ở y = 0, mặt hướng +X (như hình khối), xương Rocketbox (Bip01_*). docs/superpowers/specs/2026-11-12-nguoi-di-dao-that-design.md §5, §7 */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { ST_CLIPS, stClipMix, type StClipMix } from './anim';

const A = CONFIG.stroll.anim, NC = ST_CLIPS.length;
const ST_LOCO0 = 1, ST_LOCO1 = 3, ST_PHOTO = 4;   // chỉ số trong ST_CLIPS: walk..sprint, photo (idle = 0)

export interface StRigSource {
  scene: THREE.Object3D;                                   // cảnh gốc (không thêm vào scene; chỉ để sao chép)
  clips: THREE.AnimationClip[];                            // 5 đoạn theo thứ tự ST_CLIPS
  natural: Float32Array;                                   // tốc độ tự nhiên từng đoạn theo ST_CLIPS, m/s (idle / photo = 0)
  height: number;                                          // chiều cao tư thế đứng, m (0 nếu file không ghi)
  clone: (o: THREE.Object3D) => THREE.Object3D;            // SkeletonUtils.clone (test truyền bản giả)
}

/* Chuẩn hóa cảnh + đoạn đã nạp thành nguồn dùng chung. speeds: tên đoạn → m/s. Thiếu đoạn nào thì ném lỗi (stRigLoad bắt, trả null) */
export function stRigSource(scene: THREE.Object3D, clips: THREE.AnimationClip[], speeds: Record<string, number>, height: number, clone: (o: THREE.Object3D) => THREE.Object3D): StRigSource {
  const out: THREE.AnimationClip[] = [], natural = new Float32Array(NC);
  for (let i = 0; i < NC; i++) {
    const c = clips.find(x => x.name === ST_CLIPS[i]);
    if (!c) throw new Error(`thiếu đoạn ${ST_CLIPS[i]}`);
    out.push(c);
    natural[i] = Math.max(0, Number(speeds[ST_CLIPS[i]]) || 0);
  }
  scene.traverse((o) => {
    o.layers.set(1);
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false;
    const mats = Array.isArray(m.material) ? m.material : [m.material];
    for (const mat of mats) {
      const s = mat as THREE.MeshStandardMaterial;
      if (s.isMeshStandardMaterial) { s.metalness = 0; s.roughness = 0.85; }
      if (s.alphaTest > 0) s.transparent = false;   // MASK: cắt theo alphaTest, không trộn trong suốt (không cần sắp thứ tự)
    }
  });
  return { scene, clips: out, natural, height: height > 0 ? height : 0, clone };
}

const cache = new Map<number, Promise<StRigSource | null>>();

/* Nạp mô hình k (nhớ đệm). Không bao giờ ném / từ chối: lỗi → warn một lần, null */
export function stRigLoad(model: number): Promise<StRigSource | null> {
  let p = cache.get(model);
  if (p) return p;
  p = (async () => {
    try {
      const path = A.models[model];
      if (!path) throw new Error('không có mô hình số này');
      const [{ GLTFLoader }, SU] = await Promise.all([import('three/addons/loaders/GLTFLoader.js'), import('three/addons/utils/SkeletonUtils.js')]);
      const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + path);
      const speeds: Record<string, number> = {};
      const json = gltf.parser.json as { animations?: { name?: string; extras?: { speed?: number } }[] };   // AnimationClip không giữ extras: đọc từ JSON gốc
      for (const a of json.animations || []) if (a.name) speeds[a.name] = Number(a.extras?.speed) || 0;
      return stRigSource(gltf.scene, gltf.animations, speeds, Number(gltf.scene.userData?.height) || 0, SU.clone);
    } catch (e) {
      console.warn(`Đi dạo: không nạp được mô hình người ${model}, dùng hình khối`, e);
      return null;
    }
  })();
  cache.set(model, p);
  return p;
}

/* Một nhân vật đang diễn: bản sao của nguồn + mixer riêng */
export class StRig {
  readonly root: THREE.Object3D;
  readonly src: StRigSource;
  readonly mixer: THREE.AnimationMixer;
  readonly actions: THREE.AnimationAction[] = [];
  readonly w = new Float32Array(NC);    // trọng số đang dùng (đã làm mượt), tổng = 1
  rate = 1;                             // hệ số tua đoạn di chuyển đang dùng
  phase = 0;                            // pha chung 0–1 của walk / jog / sprint
  private readonly mix: StClipMix = { w: new Float32Array(NC), rate: 1, loco: false };
  private fresh = true;                 // lần pose đầu: đặt thẳng trọng số đích, không làm mượt
  private photo = false;                // khung trước đang ở dáng chụp ảnh

  constructor(src: StRigSource) {
    this.src = src;
    this.root = src.clone(src.scene);
    this.root.name = 'stroll-rig';
    this.mixer = new THREE.AnimationMixer(this.root);
    for (let i = 0; i < NC; i++) {
      const a = this.mixer.clipAction(src.clips[i]);
      if (i === ST_PHOTO) { a.setLoop(THREE.LoopOnce, 1); a.clampWhenFinished = true; }
      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.timeScale = 0;   // thời gian do pha chung đặt
      a.enabled = false; a.setEffectiveWeight(0); a.play();
      this.actions.push(a);
    }
  }

  /* Mỗi khung: dáng + tốc độ mặt bằng (m/s) + dt (s) → trọng số, pha, mixer.update */
  pose(pose: number, speed: number, dt: number): void {
    const d = dt > 0 ? (dt < CONFIG.stroll.dtMax ? dt : CONFIG.stroll.dtMax) : 0;   // NaN / âm → 0
    const mix = this.mix, w = this.w, acts = this.actions, clips = this.src.clips;
    stClipMix(pose, speed, this.src.natural, mix);
    const toPhoto = mix.w[ST_PHOTO] === 1;
    if (toPhoto && !this.photo) acts[ST_PHOTO].reset();   // chuyển sang chụp ảnh: giơ máy lại từ đầu
    this.photo = toPhoto;
    const k = this.fresh ? 1 : 1 - Math.exp(-d / A.fade);
    this.fresh = false;
    for (let i = 0; i < NC; i++) w[i] += (mix.w[i] - w[i]) * k;
    if (mix.loco) this.rate = mix.rate;   // đang rời nhóm di chuyển: giữ nhịp cũ trong lúc mờ dần
    let lw = 0, dur = 0;
    for (let i = ST_LOCO0; i <= ST_LOCO1; i++) { lw += w[i]; dur += w[i] * clips[i].duration; }
    if (lw > 1e-4 && dur > 1e-6) {
      const p = this.phase + d * this.rate / (dur / lw);   // chu kỳ của hỗn hợp = trung bình thời lượng theo trọng số
      this.phase = p - Math.floor(p);
    }
    for (let i = 0; i < NC; i++) {
      const a = acts[i], on = w[i] > 1e-4;
      if (i >= ST_LOCO0 && i <= ST_LOCO1) a.time = this.phase * clips[i].duration;
      if (on !== a.enabled) a.enabled = on;   // đoạn không trọng số: mixer bỏ qua, không tính
      a.setEffectiveWeight(on ? w[i] : 0);
    }
    this.mixer.update(d);
  }

  /* Đặt lại như vừa tạo: lần pose kế đặt thẳng trọng số đích */
  reset(): void { this.fresh = true; this.photo = false; this.phase = 0; this.w.fill(0); }

  /* Gỡ khỏi nhóm và bỏ mixer; geometry / texture / vật liệu thuộc nguồn dùng chung nên không dispose */
  dispose(): void {
    this.mixer.stopAllAction();
    this.mixer.uncacheRoot(this.root);
    this.root.removeFromParent();
  }
}

content.content:
1	/* ===== Đi dạo: nhân vật hiển thị (mình + tối đa 4 người khác) =====
2	   Nhóm 'stroll-people' (THREE.Group): mỗi slot đi dạo (đi một mình dùng 0) hiện bằng một nhân vật có xương (rig.ts, mô hình theo stModelFor: mình luôn 0, người khác 1 + slot mod 4).
3	   Mô hình chưa nạp xong hoặc nạp lỗi: slot hiện bằng hình khối (blocky.ts, InstancedMesh con của nhóm) nên lỗi mạng không bao giờ làm mất nhân vật.
4	   - Nạp lười: lần đầu một slot đang hiện cần mô hình k thì gọi bộ nạp (stRigLoad, test thay bằng __setLoader); kết quả chỉ vào bộ đệm sources[k].
5	     Bản sao chỉ tạo trong vòng khung (stPlace) cho slot đang hiện và đúng mô hình lúc đó, nên kết quả về muộn (slot đã đổi chủ, đã trống, đã rời chế độ) không bao giờ gắn nhầm (Review Focus 2).
6	   - Slot đổi chủ / đổi mô hình / clear(): gỡ bản sao khỏi nhóm, bỏ mixer (StRig.dispose; geometry / texture của nguồn dùng chung giữ lại).
7	   - dt cho mixer: mình nhận dt của bước chuyển động qua setSelf; người khác dùng hiệu nowMs giữa hai lần update; StRig kẹp ≤ stroll.dtMax (Review Focus 3).
8	   - Người khác nội suy bằng ExTrack như remote.ts (trường thứ 6 chở pose, lấy mẫu bậc thang step = true); slot đổi chủ thì xóa mẫu và ẩn tới mẫu đầu.
9	   Lớp 1, không đổ bóng (rig.ts, blocky.ts). build() chỉ dựng (lần đầu gọi, không lúc dựng cảnh), bên gọi tự thêm vào scene. Không cấp phát mỗi khung (D-018). */
10	import * as THREE from 'three';
11	import { CONFIG } from '../../config';
12	import { ExTrack, type ExPose } from '../multi/interp';
13	import type { Flyer } from '../multi/protocol';
14	import { ST_POSE_WALK, ST_POSE_RUN, type StState } from './motion';
15	import { stModelFor } from './anim';
16	import { stBlocky } from './blocky';
17	import { stRigLoad, StRig, type StRigSource } from './rig';
18	
19	export { stAvatarVar } from './blocky';
20	
21	const M = CONFIG.explore.multi, C = CONFIG.stroll, N = M.stroll.slots;
22	
23	interface StSlot {
24	  who: 0 | 1 | 2;             // 0 trống, 1 mình, 2 người khác
25	  name: string | null;        // tên người khác (từ sync); null = không có
26	  track: ExTrack;
27	  pose: ExPose;               // đệm lấy mẫu (bank chở pose)
28	  st: { x: number; y: number; z: number; yaw: number; pose: number };   // trạng thái trả cho slotState
29	  live: boolean;              // đang hiện
30	  rig: StRig | null;          // nhân vật có xương đang gắn (null: hình khối)
31	  model: number;              // mô hình của rig
32	}
33	
34	const slots: StSlot[] = Array.from({ length: N }, () => ({
35	  who: 0 as const, name: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
36	  st: { x: 0, y: 0, z: 0, yaw: 0, pose: 0 }, live: false, rig: null, model: -1
37	}));
38	let group: THREE.Group | null = null, me = -1, lastNow = -1;
39	
40	/* Bộ đệm mô hình: undefined = chưa có kết quả, null = nạp lỗi (giữ hình khối, không thử lại), còn lại = nguồn */
41	let loader: (model: number) => Promise<StRigSource | null> = stRigLoad;
42	let sources: (StRigSource | null | undefined)[] = [];
43	let asked = new Set<number>();
44	let gen = 0;   // thế hệ bộ nạp: __setLoader tăng để kết quả của bộ nạp cũ bị bỏ
45	
46	/* Nguồn của mô hình k nếu đã nạp xong; chưa thì bắt đầu nạp (một lần) và trả null. Không ném */
47	function stNeed(model: number): StRigSource | null {
48	  const s = sources[model];
49	  if (s !== undefined) return s;
50	  if (!asked.has(model)) {
51	    asked.add(model);
52	    const g = gen;
53	    const done = (r: StRigSource | null) => { if (g === gen) sources[model] = r; };
54	    try { loader(model).then(done, () => done(null)); } catch { done(null); }
55	  }
56	  return null;
57	}
58	
59	/* Gỡ nhân vật thật của slot i (đổi chủ, đổi mô hình, rời chế độ) */
60	function stDrop(i: number): void {
61	  const s = slots[i];
62	  if (!s.rig) return;
63	  s.rig.dispose(); s.rig = null; s.model = -1;
64	}
65	
66	/* Đặt slot i theo s.st: nhân vật thật nếu mô hình đã có, không thì hình khối. speed (m/s) chọn đoạn / nhịp bước, dt (s) cho mixer */
67	function stPlace(i: number, speed: number, dt: number): void {
68	  const s = slots[i];
69	  if (!group) return;
70	  if (!s.live) { stBlocky.place(i, null, 0); if (s.rig) s.rig.root.visible = false; return; }
71	  const model = stModelFor(i, s.who === 1);
72	  if (s.rig && s.model !== model) stDrop(i);
73	  if (!s.rig) {
74	    const src = stNeed(model);
75	    if (src) { s.rig = new StRig(src); s.model = model; group.add(s.rig.root); }
76	  }
77	  const t = s.st;
78	  if (!s.rig) { stBlocky.place(i, t, speed); return; }
79	  stBlocky.place(i, null, 0);
80	  const r = s.rig.root;
81	  r.visible = true;
82	  r.position.set(t.x, t.y, t.z); r.rotation.set(0, t.yaw, 0);   // mô hình hướng +X như hình khối: yaw quanh Y
83	  s.rig.pose(t.pose, speed, dt);
84	}
85	
86	function stHide(i: number): void {
87	  const s = slots[i];
88	  s.track.reset(); s.live = false;
89	  stDrop(i);
90	  stPlace(i, 0, 0);
91	}
92	
93	function stRefreshVisible(): void {
94	  if (!group) return;
95	  let any = false;
96	  for (const s of slots) if (s.live) { any = true; break; }
97	  group.visible = any;
98	  stBlocky.refresh();
99	}
100	
101	/* Tốc độ danh định theo dáng cho người khác (gói vị trí không có tốc độ) */
102	const stPoseSpeed = (pose: number) => (pose === ST_POSE_RUN ? C.run : pose === ST_POSE_WALK ? C.walk : 0);
103	
104	export const stAvatars = {
105	  get mesh(): THREE.Group | null { return group; },
106	  get self(): number { return me; },   // slot nhân vật của mình, -1 nếu không có (nhãn tên bỏ qua slot này)
107	
108	  /* Dựng lần đầu gọi (lười, ngoài thứ tự dựng cảnh), các lần sau trả lại nhóm cũ. Bên gọi thêm vào scene */
109	  build(): THREE.Group {
110	    if (group) return group;
111	    group = new THREE.Group();
112	    group.name = 'stroll-people';
113	    group.add(stBlocky.build());
114	    group.visible = false;
115	    return group;
116	  },
117	
118	  /* Bắt đầu nạp mô hình (mặc định 0, nhân vật của mình) trước khi cần, vd. lúc chọn thẻ Đi dạo. Không ném */
119	  preload(model = 0): void { stNeed(model); },
120	
121	  /* Nhân vật của mình ở slot (đi một mình: 0); s = null thì bỏ hiện slot đó. dt (s): bước chuyển động vừa chạy, cho mixer */
122	  setSelf(slot: number, s: StState | null, dt = 0): void {
123	    if (s === null) {
124	      if (me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
125	      me = -1; stRefreshVisible(); return;
126	    }
127	    const x = slots[slot];
128	    if (!x) return;
129	    if (me !== slot && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
130	    if (x.who !== 1) stDrop(slot);   // slot vừa thành của mình: bản sao người khác (nếu còn) bỏ
131	    me = slot; x.who = 1; x.track.reset();
132	    const t = x.st;
133	    t.x = s.x; t.y = s.y; t.z = s.z; t.yaw = s.yaw; t.pose = s.pose;
134	    x.live = true;
135	    stPlace(slot, s.speed, dt);
136	    stRefreshVisible();
137	  },
138	
139	  /* Danh sách người đi dạo đổi (sảnh, vào, ra): slot đổi chủ thì xóa mẫu, ẩn tới mẫu đầu; slot trống thì ẩn. Slot của mình do setSelf lo */
140	  sync(walkers: Flyer[], mySlot: number): void {
141	    if (mySlot !== me && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); me = -1; }   // đổi slot của mình: setSelf sẽ đặt lại
142	    for (let i = 0; i < N; i++) {
143	      const s = slots[i];
144	      let name: string | null = null;
145	      for (const w of walkers) if (w.slot === i) { name = w.name; break; }
146	      if (i === mySlot) { s.name = name; if (s.who === 2) { s.who = 0; stHide(i); } continue; }   // slot vừa thành của mình: bỏ người khác cũ, chờ setSelf
147	      if (name === null) { s.name = null; if (s.who === 2) { s.who = 0; stHide(i); } continue; }
148	      if (name !== s.name || s.who !== 2) { s.name = name; s.who = 2; stHide(i); }
149	    }
150	    stRefreshVisible();
151	  },
152	
153	  /* Gói vị trí gộp: w = [slot, x, y, z, yaw, pose, giờ gửi?]; chỉ nhận slot người khác đã biết chủ */
154	  onPos(w: number[][], nowMs: number): void {
155	    for (const e of w) {
156	      const i = e[0], s = slots[i];
157	      if (!s || i === me || s.who !== 2) continue;
158	      s.track.feed(e, nowMs, M);
159	    }
160	  },
161	
162	  /* Mỗi khung: đặt người khác theo mẫu nội suy (pose bậc thang); dt mixer = hiệu nowMs giữa hai lần gọi (StRig kẹp dtMax) */
163	  update(nowMs: number): void {
