1	/* ============================ Đi dạo: chọn và trộn đoạn chuyển động của nhân vật có xương (thuần) ============================
2	   Từ dáng (pose) và tốc độ mặt bằng (m/s) tính trọng số năm đoạn idle / walk / jog / sprint / photo và hệ số tua `rate` cho đoạn di chuyển.
3	   Thuần: không import three, không đụng DOM, không cấp phát (gọi mỗi khung cho từng nhân vật, D-018): kết quả ghi vào `out` do bên gọi giữ.
4	   - Di chuyển (pose 1, 2 và 3 khi còn tốc độ ngang): trộn theo tốc độ, walk (≤ walkTo) → jog (jogAt) → sprint (≥ sprintFrom), tuyến tính giữa các mốc; dáng đi / chạy chỉ cho biết đang di chuyển.
5	   - rate = tốc độ thật / tốc độ tự nhiên của đoạn trộn, kẹp [rateMin, rateMax]: chân chạm đất gần đúng không trượt.
6	   - Dáng lạ (khách bản cũ, số ngoài 0..4, NaN) và rơi không còn tốc độ ngang: đứng yên (idle). Khách bản cũ gửi dáng 3 khi nhảy; người đó hiện đứng yên. */
7	import { CONFIG } from '../../config';
8	import { ST_POSE_WALK, ST_POSE_RUN, ST_POSE_FALL, ST_POSE_PHOTO } from './motion';
9	
10	export const ST_CLIPS = ['idle', 'walk', 'jog', 'sprint', 'photo'] as const;
11	export type StClip = typeof ST_CLIPS[number];
12	
13	export interface StClipMix {
14	  w: Float32Array;   // 5 trọng số theo thứ tự ST_CLIPS, tổng = 1
15	  rate: number;      // hệ số tua đoạn di chuyển
16	  loco: boolean;     // đang di chuyển (walk / jog / sprint có trọng số)
17	}
18	
19	const A = CONFIG.stroll.anim;
20	
21	export function stClipMix(pose: number, speed: number, natural: ArrayLike<number>, out: StClipMix): void {
22	  const w = out.w, v = speed > 0 ? speed : 0;
23	  w[0] = 0; w[1] = 0; w[2] = 0; w[3] = 0; w[4] = 0;
24	  out.rate = 1; out.loco = false;
25	  if (pose === ST_POSE_PHOTO) { w[4] = 1; return; }
26	  const move = pose === ST_POSE_WALK || pose === ST_POSE_RUN || (pose === ST_POSE_FALL && v >= A.fallMin);
27	  if (!move) { w[0] = 1; return; }
28	  out.loco = true;
29	  if (v <= A.walkTo) w[1] = 1;
30	  else if (v < A.jogAt) { const t = (v - A.walkTo) / (A.jogAt - A.walkTo); w[1] = 1 - t; w[2] = t; }
31	  else if (v < A.sprintFrom) { const t = (v - A.jogAt) / (A.sprintFrom - A.jogAt); w[2] = 1 - t; w[3] = t; }
32	  else w[3] = 1;
33	  const nat = w[1] * natural[1] + w[2] * natural[2] + w[3] * natural[3];
34	  const r = nat > 1e-6 ? v / nat : 1;
35	  out.rate = r < A.rateMin ? A.rateMin : r > A.rateMax ? A.rateMax : r;
36	}
37	
38	/* Mô hình của slot: mình luôn mô hình 0; người khác dùng 1..others theo slot (slot âm vẫn trong khoảng) */
39	export function stModelFor(slot: number, isSelf: boolean): number {
40	  if (isSelf) return 0;
41	  const n = A.others;
42	  return 1 + (((slot % n) + n) % n);
43	}
44

