1	/* ===== Đi dạo: 5 file nhân vật public/people/p0..p4.glb (sinh bằng scripts/people/convert.py) — đọc phần JSON của GLB, không cần three ===== */
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { readFileSync, existsSync, statSync } from 'node:fs';
5	import { fileURLToPath } from 'node:url';
6	import { join, dirname } from 'node:path';
7	
8	const DIR = join(dirname(fileURLToPath(import.meta.url)), '../../public/people');
9	const MB = 1024 * 1024;
10	const K = [0, 1, 2, 3, 4];
11	
12	/* Đọc khối JSON đầu tiên của file GLB (header 12 byte, rồi chunk JSON) */
13	function glbJson(file: string): any {
14	  const b = readFileSync(file);
15	  assert.equal(b.readUInt32LE(0), 0x46546c67, 'không phải GLB');            // 'glTF'
16	  const len = b.readUInt32LE(12), type = b.readUInt32LE(16);
17	  assert.equal(type, 0x4e4f534a, 'chunk đầu không phải JSON');              // 'JSON'
18	  return JSON.parse(b.subarray(20, 20 + len).toString('utf8'));
19	}
20	
21	test('5 file tồn tại, mỗi file ≤ 1,5 MB, tổng ≤ 6 MB', () => {
22	  let sum = 0;
23	  for (const k of K) {
24	    const f = join(DIR, `p${k}.glb`);
25	    assert.ok(existsSync(f), `thiếu p${k}.glb`);
26	    const n = statSync(f).size; sum += n;
27	    assert.ok(n <= 1.5 * MB, `p${k}.glb ${n} byte > 1,5 MB`);
28	  }
29	  assert.ok(sum <= 6 * MB, `tổng ${sum} byte > 6 MB`);
30	});
31	
32	for (const k of K) {
33	  test(`p${k}.glb: 5 đoạn đúng tên, speed hợp lý, 1 skin, không nén, có height`, () => {
34	    const j = glbJson(join(DIR, `p${k}.glb`));
35	    const anims: any[] = j.animations ?? [];
36	    assert.deepEqual(anims.map(a => a.name).sort(), ['idle', 'jog', 'photo', 'sprint', 'walk']);
37	    const sp: Record<string, number> = {};
38	    for (const a of anims) { assert.equal(typeof a.extras?.speed, 'number', `${a.name} thiếu extras.speed`); sp[a.name] = a.extras.speed; }
